-- 054 — новые пулы ключей: 1464 для сайтов + 157 для поиска TG-каналов
--
-- ── Куда именно они легли, и почему не туда, где написано в файлах ──────────
-- Файлы от Ника адресуют INSERT в `brand_keywords`. Такая таблица существует,
-- но это НЕ то, чем кажется: её схема (brand_target_id, keyword, modifier,
-- lang) относится к пайплайну brand-search — поиску по конкретным сайтам-целям,
-- а не по гео. Ни колонки geo, ни layer, ни brand_id там нет; INSERT из файлов
-- в неё просто не выполнится.
--
-- Схема, совпадающая с файлами колонка в колонку — `multibrand_keywords`
-- (brand_id, geo, language, keyword, layer, active) из 038. Туда и льём.
-- Новых таблиц не создано, как и требует ТЗ.
--
-- ── Полная замена, а не дополнение (ТЗ §4.2) ────────────────────────────────
-- Старый сид 040 покрывает те же гео более узкими формулировками
-- («casino affiliate program» — поиск партнёрок, а не игроков). Смешивать
-- нельзя: это две разные механики поиска, и вперемешку они дают ключи, про
-- которые потом не понять, почему они не работают.
--
-- ── Учёт выработки (ТЗ §5) ──────────────────────────────────────────────────
-- ТЗ просит смотреть «результатов на запрос» в разрезе языка и выключать
-- пустые ключи. Померить это по multibrand_keywords было нечем — колонок
-- выработки в 038 нет. Добавляем их здесь: без них раздел 5 невыполним, а
-- 1464 ключа без отбраковки — это 1464 тика крона, часть которых заведомо
-- впустую (KK, KY, MN, SI, UR, SO, AZ, MY, FA, TH, VI, ID сгенерированы
-- шаблоном без носителя).
ALTER TABLE public.multibrand_keywords ADD COLUMN IF NOT EXISTS runs          INTEGER NOT NULL DEFAULT 0;
ALTER TABLE public.multibrand_keywords ADD COLUMN IF NOT EXISTS results_found INTEGER NOT NULL DEFAULT 0;
ALTER TABLE public.multibrand_keywords ADD COLUMN IF NOT EXISTS leads_created INTEGER NOT NULL DEFAULT 0;
ALTER TABLE public.multibrand_keywords ADD COLUMN IF NOT EXISTS last_run_at   TIMESTAMPTZ;

-- Обход пула строго по last_run_at NULLS FIRST — тот же приём, что в 029:
-- гарантирует, что каждый ключ дойдёт до очереди, а не что мы вечно крутим
-- первые пять.
CREATE INDEX IF NOT EXISTS multibrand_kw_rotation
  ON public.multibrand_keywords (brand_id, layer, last_run_at NULLS FIRST) WHERE active;

CREATE UNIQUE INDEX IF NOT EXISTS multibrand_keywords_dedup
  ON public.multibrand_keywords (brand_id, geo, language, keyword);

-- ── Заливка ─────────────────────────────────────────────────────────────────
-- Строки перенесены из файлов ПРОГРАММНО, вручную не переписывались: 1464
-- строки, а опечатка в ключе — это тихо потраченный тик крона, который никто
-- никогда не заметит.
DELETE FROM public.multibrand_keywords
 WHERE brand_id IN (SELECT id FROM public.brands WHERE slug IN ('1xbet','1xcasino','luckypari'));


-- ════════════════════════════════════════════════════════════════════════════
-- 2. Ключи поиска TG-каналов
-- ════════════════════════════════════════════════════════════════════════════
-- Целевая таблица (плейсхолдер <TG_KEYWORDS_TABLE> из файла) — это
-- `tg_search_queries` из 020: её читает scan-tg-channels.ts. Своя таблица у
-- TG-пайплайна была с самого начала, новой не заводим.
--
-- В ней не было ни бренда, ни гео, ни языка, ни слоя — только текст запроса и
-- счётчики. ТЗ требует brand_id у всех 157 строк, а разрез по языку нужен для
-- §5, поэтому колонки добавляются к существующей таблице.
ALTER TABLE public.tg_search_queries ADD COLUMN IF NOT EXISTS brand_id UUID REFERENCES public.brands(id);
ALTER TABLE public.tg_search_queries ADD COLUMN IF NOT EXISTS geo      TEXT;
ALTER TABLE public.tg_search_queries ADD COLUMN IF NOT EXISTS language TEXT;
ALTER TABLE public.tg_search_queries ADD COLUMN IF NOT EXISTS layer    TEXT NOT NULL DEFAULT 'A';

CREATE INDEX IF NOT EXISTS tg_search_queries_brand_idx
  ON public.tg_search_queries (brand_id, layer, last_run_at NULLS FIRST) WHERE active;

-- Старый сид 020 ВЫКЛЮЧАЕТСЯ, а не удаляется (ТЗ §5: «выключать через
-- active=false, не удалять, чтобы видеть, что уже отбраковано»). Плюс у тех
-- строк накоплены runs/channels_found — статистика, по которой видно, какие
-- углы вообще работали. Удалить её значит потерять единственное имеющееся
-- измерение TG-поиска.
UPDATE public.tg_search_queries SET active = false WHERE brand_id IS NULL;

-- ON CONFLICT по существующему UNIQUE(query): часть новых запросов совпадает
-- со старым сидом дословно, и такую строку надо не пропустить, а достроить
-- брендом и слоем — иначе она осталась бы выключенной строкой выше.
ON CONFLICT (query) DO UPDATE
  SET brand_id = EXCLUDED.brand_id,
      geo      = EXCLUDED.geo,
      language = EXCLUDED.language,
      layer    = EXCLUDED.layer,
      active   = true;

-- ════════════════════════════════════════════════════════════════════════════
-- 3. Дедуп TG-каналов по username, а не по ссылке (ТЗ §3.4)
-- ════════════════════════════════════════════════════════════════════════════
-- Канонизация в scan-tg-channels.ts уже сводила t.me/s/x, telegram.me/x и
-- t.me/x/123 к одному https://t.me/x — но СОХРАНЯЛА регистр. А username в
-- Telegram регистронезависим: t.me/BettingTips и t.me/bettingtips — один и тот
-- же канал, и в базе они лежали двумя строками. UNIQUE(channel_url) этого не
-- ловит: строки-то разные.
--
-- Наружу это выглядит как «оператору второй раз прилетела та же карточка».
--
-- Отдельную колонку под нормализованный username не заводим сознательно:
-- upsert в scan-tg-channels идёт через PostgREST с on_conflict=channel_url, а
-- тот умеет только настоящий UNIQUE-констрейнт, не функциональный индекс. Если
-- канонической формой сделать сам channel_url (username в нижнем регистре),
-- существующий констрейнт начинает работать правильно без единой правки в
-- пути записи.

-- 3.1 Схлопнуть уже накопленные дубли: оставляем самую раннюю строку, потому
--     что на ней висит история в tg_outreach_log и, возможно, уже пройденный
--     статус (contacted/rejected). Потерять именно её значит написать человеку
--     второй раз — ровно то, что ТЗ запрещает.
-- Обычная таблица, а не TEMP ... ON COMMIT DROP, и это не небрежность.
-- Миграции этого репозитория прогоняются и одним батчем через Management API
-- (тогда всё внутри одной неявной транзакции), и по одному запросу через psql
-- (тогда каждый оператор — своя транзакция). Во втором случае temp-таблица с
-- ON COMMIT DROP исчезла бы сразу после своего CREATE, и следующий оператор
-- упал бы на «relation does not exist». Обычная таблица ведёт себя одинаково
-- в обоих режимах; удаляем её явно в конце раздела.
DROP TABLE IF EXISTS public.tg_dedup_map;
CREATE UNLOGGED TABLE public.tg_dedup_map AS
WITH canon AS (
  SELECT id,
         'https://t.me/' || lower(regexp_replace(channel_url,
            '^https?://(www\.)?(t|telegram)\.me/(s/)?', '', 'i')) AS canon_url
    FROM public.tg_outreach_channels
)
SELECT c.id AS dup_id,
       first_value(c.id) OVER (PARTITION BY c.canon_url ORDER BY c.id) AS keep_id,
       c.canon_url
  FROM canon c;

-- История дублей переезжает на выжившую строку, а не исчезает вместе с ними:
-- FK стоит ON DELETE CASCADE, так что без этого шага записи журнала молча
-- удалились бы, и «почему этот канал отклонён» стало бы неотвечаемым.
UPDATE public.tg_outreach_log l
   SET channel_id = m.keep_id
  FROM public.tg_dedup_map m
 WHERE l.channel_id = m.dup_id AND m.dup_id <> m.keep_id;

DELETE FROM public.tg_outreach_channels c
 USING public.tg_dedup_map m
 WHERE c.id = m.dup_id AND m.dup_id <> m.keep_id;

UPDATE public.tg_outreach_channels c
   SET channel_url = m.canon_url
  FROM public.tg_dedup_map m
 WHERE c.id = m.keep_id AND c.channel_url <> m.canon_url;

DROP TABLE public.tg_dedup_map;

-- 3.2 Страховка на будущее. Констрейнт выше защищает от точного повтора, этот
--     индекс — от повтора, отличающегося регистром, если канонизация в коде
--     когда-нибудь снова начнёт его сохранять. Проверка, а не механизм записи.
CREATE UNIQUE INDEX IF NOT EXISTS tg_outreach_channels_username_uniq
  ON public.tg_outreach_channels (lower(channel_url));

-- ════════════════════════════════════════════════════════════════════════════
-- 3.5 Первый прогон — только 1xBet (ТЗ §4.6)
-- ════════════════════════════════════════════════════════════════════════════
-- До этой миграции 1xcasino и luckypari имели пул, которого не существовало
-- для пайплайна, и find-and-queue честно откатывался на 1xbet при каждом
-- выпадении. Теперь пул у них есть — а значит их cron_weight (25 и 25 из 100
-- по 035) немедленно уводит ПОЛОВИНУ прогонов на бренды, чей дедуп ещё никто
-- не наблюдал в бою.
--
-- ТЗ прямо просит этого не делать: сначала 1xBet, остальные — после того как
-- в логе станет видно число отфильтрованных дублей.
--
-- Включить обратно, когда подтвердится (правка одной строкой, без деплоя):
--   UPDATE public.brands SET cron_weight = 25 WHERE slug IN ('1xcasino','luckypari');
UPDATE public.brands SET cron_weight = 0 WHERE slug IN ('1xcasino','luckypari');

-- ════════════════════════════════════════════════════════════════════════════
-- 4. Проверка
-- ════════════════════════════════════════════════════════════════════════════
-- Числа из ТЗ §6 сверяются прямо здесь: заливка, прошедшая наполовину, снаружи
-- выглядит как работающая, и обнаружится через неделю по пустой выдаче.
DO $$
DECLARE n INT; nb INT; s TEXT;
BEGIN
  FOR s, nb IN
    SELECT slug, cnt FROM (VALUES ('1xbet',929),('1xcasino',263),('luckypari',272)) AS v(slug,cnt)
  LOOP
    SELECT count(*) INTO n FROM public.multibrand_keywords k
      JOIN public.brands b ON b.id = k.brand_id WHERE b.slug = s;
    IF n <> nb THEN
      RAISE EXCEPTION 'ожидалось % ключей для %, найдено %', nb, s, n;
    END IF;
  END LOOP;

  SELECT count(*) INTO n FROM public.tg_search_queries WHERE brand_id IS NOT NULL;
  IF n <> 157 THEN RAISE EXCEPTION 'ожидалось 157 TG-ключей с брендом, найдено %', n; END IF;

  SELECT count(*) INTO n FROM public.tg_search_queries q
    JOIN public.brands b ON b.id = q.brand_id WHERE b.slug <> '1xbet';
  IF n > 0 THEN RAISE EXCEPTION 'TG-ключи должны быть только под 1xbet, чужих: %', n; END IF;

  -- Ключ без языка или гео не отбраковать по §5 — метрика «результатов на
  -- запрос в разрезе языка» на нём просто не считается.
  SELECT count(*) INTO n FROM public.multibrand_keywords
   WHERE coalesce(language,'') = '' OR coalesce(geo,'') = '';
  IF n > 0 THEN RAISE EXCEPTION 'у % ключей нет языка или гео', n; END IF;

  SELECT count(*) INTO n FROM public.tg_outreach_channels
   WHERE channel_url <> lower(channel_url);
  IF n > 0 THEN RAISE EXCEPTION '% TG-каналов остались не в нижнем регистре', n; END IF;

  SELECT count(*) INTO n FROM (
    SELECT lower(channel_url) FROM public.tg_outreach_channels
     GROUP BY 1 HAVING count(*) > 1) d;
  IF n > 0 THEN RAISE EXCEPTION '% TG-каналов дублируются по username', n; END IF;

  SELECT count(*) INTO n FROM public.brands
   WHERE slug IN ('1xcasino','luckypari') AND cron_weight <> 0;
  IF n > 0 THEN RAISE EXCEPTION 'у % брендов cron_weight не 0 — первый прогон должен быть только 1xBet', n; END IF;

  SELECT count(*) INTO n FROM public.multibrand_keywords;
  RAISE NOTICE 'ключей сайтов: %, TG-ключей под 1xbet: 157, дублей TG-каналов нет', n;
END $$;
